// Cambia aquí el NIT del cliente (sin dígito de verificación) y ejecuta el flujo.
const nit = '901314381';
const limpio = String(nit).replace(/\D/g, '');
const bqQuery = "SELECT nit_cliente, razon_social, nit_contraparte, razon_social_contraparte, correos_notificacion " +
  "FROM `inlaid-stack-375114.analytics_data_products.mapping_rules` WHERE nit_cliente = '" + limpio + "'";
return [{ json: { nit: limpio, bqQuery } }];

// Resume qué trae la columna correos_notificacion para el cliente consultado.
const resp = $input.first().json || {};
if (resp.jobComplete === false) {
  return [{ json: { resultado: 'BigQuery no terminó a tiempo. Vuelve a ejecutar el flujo.' } }];
}
const fields = (resp.schema && resp.schema.fields) || [];
const rows = (resp.rows || []).map(row => { const o = {}; row.f.forEach((c, i) => { o[fields[i].name] = c.v; }); return o; });
const nit = $('NIT a consultar').first().json.nit;
if (!rows.length) return [{ json: { nit, resultado: 'El NIT no aparece como cliente en mapping_rules.' } }];
const limpio = v => (v == null ? '' : String(v).trim());
const distintos = [...new Set(rows.map(r => limpio(r.correos_notificacion)).filter(Boolean))];
const conCorreo = rows.filter(r => limpio(r.correos_notificacion)).length;
let lectura;
if (!distintos.length) lectura = 'VACÍO: ninguna fila trae correo. Hay que definir otra fuente con Álvaro.';
else if (distintos.length === 1 && conCorreo === rows.length) lectura = 'UN SOLO CORREO en todas las filas: parece ser el correo del cliente.';
else lectura = 'CAMBIA SEGÚN EL PAGADOR (o no todas las filas lo traen): parece ser el correo del pagador, no del cliente.';
return [{ json: {
  nit, cliente: rows[0].razon_social, filas: rows.length, filasConCorreo: conCorreo,
  correosDistintos: distintos, lectura,
  detallePorPagador: rows.map(r => ({ pagador: r.razon_social_contraparte, nitPagador: r.nit_contraparte, correo: limpio(r.correos_notificacion) || '(vacío)' }))
} }];
